#pragma once#include "BaseReader.h"class K8DI : public KBaseReader{public:  K8DI();  virtual std::string GetType() const  {    return "8DI";  }  virtual void GetSettings( tVectoredString_ &set, tParamsCont_ &params )  {    __super::GetSettings( set, params );    set = m_settings;  }protected:  virtual BOOL OnParsingSingleText( std::string &szText, RECTL *rc );private:  int m_CurParameterID;  int m_ReadParams;  tVectoredString_ m_settings;  std::string szLast;  int firstIndex;};//////////////////////////////////////////////////////////////////////////class K8DIFactory : public TIntrusivePtrImpl<IParamReaderFactory>{public:  virtual IParameterReadPtr CreateReader()  {    IParameterReadPtr ptr;    ptr = new K8DI();    return ptr;  }};